import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

/**
 * The launcher and launch-screen PNGs must match what they were rendered from.
 *
 * `mobile/assets/images/*.png` are generated by `npm run icons:render` from the mascot and the
 * palette constants. Nothing checked that they kept up, and the cost of that was not
 * hypothetical: `docs/palette-migration.md` carried "step 3 is still open — the assets were last
 * touched before this palette landed, so they are probably stale" for four days. The word
 * *probably* is the tell. Settling it took six `git log` queries to establish that every input
 * predates the render and the assets were fine all along.
 *
 * That is a question a hash answers in milliseconds, and the doc had already gone stale once
 * before in the same section — it opens by correcting an earlier claim that steps 1–5 were all
 * undone when three were finished. Status tracked in prose rots. This is the same rule the rest
 * of the repo already follows: a comment records a decision, a test keeps it.
 *
 * Deliberately hashing the *sources* rather than re-rendering to compare PNGs. Re-rendering
 * needs Remotion and a headless Chrome on every CI run to answer a question a checksum answers
 * for free, and Remotion downloads its own browser, which is blocked in exactly the sandboxed
 * environments this suite runs in.
 *
 * The input list lives in the manifest because `render-brand-assets.mjs` writes it there. This
 * test does not keep a second copy to drift against — it checks the files the renderer says it
 * read.
 */

const MANIFEST = "scripts/build/render-manifest.json";

describe("brand assets", () => {
  const manifest = JSON.parse(readFileSync(join(process.cwd(), MANIFEST), "utf8")) as {
    inputs: string[];
    sha256: string;
  };

  it("names the sources it was rendered from", () => {
    // A manifest that lists nothing would hash to a constant and pass forever.
    expect(manifest.inputs.length).toBeGreaterThan(0);
    expect(manifest.sha256).toMatch(/^[0-9a-f]{64}$/);
  });

  it("is current with the mascot and the palette constants", () => {
    // Path then bytes, in list order — byte-identical to `hashInputs` in the render script, so a
    // rename counts as a change rather than hashing the same as before.
    const sha = createHash("sha256");
    for (const rel of manifest.inputs) {
      sha.update(rel);
      sha.update(readFileSync(join(process.cwd(), rel), "utf8").replace(/\r\n/g, "\n"));
    }

    expect(
      sha.digest("hex"),
      `${manifest.inputs.join(", ")} have changed since the brand assets were rendered — run \`npm run icons:render\` and commit the PNGs`,
    ).toBe(manifest.sha256);
  });
});
